def longest_run(xs):
    xs = [x for x in xs if x >= 3]
    if not xs:
        return 0

    max_run = 1
    current_run = 1

    for i in range(1, len(xs)):
        if xs[i] == xs[i - 1]:
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 1

    return max_run
```

