def run_machine(program):
    stack = []
    for instruction in program:
        if instruction.startswith('PUSH'):
            _, v = instruction.split()
            v = int(v)
            stack.append(v)
        elif instruction == 'TWIST':
            _, a, b = instruction.split()
            stack[-1] = (stack[-1] * 3 + 1) % 10000
        elif instruction == 'SUBR':
            _, a, b = instruction.split()
            stack[-1] = (stack[-1] - int(b)) % 10000
        elif instruction == 'DUP':
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if stack:
                top1, top2 = stack.pop(), stack.pop()
                stack.append(top2)
                stack.append(top1)
        elif instruction.startswith('ADD'):
            _, b, c = instruction.split()
            b = int(b)
            c = int(c)
            stack[-1] = (stack[-1] + b) % 10000
        elif instruction.startswith('SUBR'):
            _, a, b = instruction.split()
            a = int(a)
            b = int(b)
            stack[-1] = (stack[-1] - a) % 10000
        elif instruction.startswith('PUSH'):
            _, v = instruction.split()
            stack.append(int(v))
        elif instruction == 'SWAP':
            if stack:
                top1, top2 = stack.pop(), stack.pop()
                stack.append(top1)
                stack.append(top2)
        elif instruction == 'SWAP':
            if stack:
                top1, top2 = stack.pop(), stack.pop()
                stack.append(top2)
                stack.append(top1)
        elif instruction == 'PUSH':
            _, v = instruction.split()
            stack.append(int(v))
    return stack[-1] if stack else -1
