    return order

def graph(n, edges):
    graph = [set() for _ in range(n)]
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)
    return graph

# Example usage:
bfs_order(6, [[1, 4], [0, 2]]) == [0, 2]
